import json
from pathlib import Path

def load_config(override_path):
    config = json.loads(Path('configs/default.json').read_text())
    config.update(json.loads(Path(override_path).read_text()))
    return config

def prepare_inputs(by_scene, config):
    if config['normalization'] == 'shared':
        values = [x for xs in by_scene.values() for x in xs]
        center = sum(values) / len(values)
        return {scene: [x - center for x in xs] for scene, xs in by_scene.items()}
    return {scene: [x - sum(xs) / len(xs) for x in xs] for scene, xs in by_scene.items()}
